'use client';
import {useCallback,useEffect,useMemo,useState} from 'react';
import {LayoutDashboard,Store,MapPinned,ClipboardList,ShoppingBag,Wallet,Users,Package,Settings,Plus,ArrowUpRight,ArrowRight,Search,ChevronRight,MapPin,Navigation,CalendarDays,Check,CheckCircle2,Clock,Download,ExternalLink,Phone,Truck,Receipt,RefreshCw,ShieldCheck,LogOut,AlertCircle,LoaderCircle,Trash2,PawPrint,Info,Menu,Mail,ChevronDown} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarHeader,SidebarContent,SidebarFooter,SidebarGroup,SidebarGroupLabel,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarInset,SidebarTrigger,useSidebar} from '@/components/ui/sidebar';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {Sheet,SheetContent,SheetHeader,SheetTitle,SheetDescription} from '@/components/ui/sheet';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
import {Table,TableHeader,TableHead,TableRow,TableBody,TableCell} from '@/components/ui/table';
import {Skeleton} from '@/components/ui/skeleton';
import {toast,Toaster} from 'sonner';
import {shopStates,visitResults,orderStates,models,colors,defaults,commissionSummary} from '@/lib/domain';
import {workspaceRequest} from '@/lib/auth';
import {AccessLink} from './access-link';
import {demoData} from '@/lib/demo';
type Row=Record<string,any>;
const nav=[['overview','Inicio',LayoutDashboard],['shops','Comercios',Store],['routes','Recorridos',MapPinned],['visits','Visitas',ClipboardList],['orders','Pedidos',ShoppingBag],['payments','Cobros',Wallet],['sellers','Vendedores',Users],['kits','Material',Package],['settings','Configuración',Settings]] as const;
const money=(n:number)=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n||0);
const date=(s:string)=>s?new Date(s.includes('T')?s:s+'T12:00:00').toLocaleDateString('es-AR',{day:'2-digit',month:'short'}):'Sin fecha';
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'America/Argentina/Mendoza'});
const id=(prefix='')=>prefix+Array.from(crypto.getRandomValues(new Uint8Array(8)),b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();
const directions=(s:Row)=>'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(s.address);
const phone=(s:string)=>'https://wa.me/'+s.replace(/\D/g,'');
function Badge({value}:{value:string}){const green=['Cliente','Entregado','Cobrado','Abonada','Hizo pedido','Activo'];const amber=['Interesado','Preparado','Parcial','Por abonar','Volver a visitar'];return <span className={'badge '+(green.includes(value)?'green':amber.includes(value)?'amber':value==='Cancelado'||value==='No interesado'?'gray':'blue')}>{value}</span>}
function Pick({value,onChange,options,label,placeholder='Seleccioná una opción'}:{value:string,onChange:(v:string)=>void,options:any[],label?:string,placeholder?:string}){return <Select value={value||'__none'} onValueChange={v=>onChange(v==='__none'?'':v)}><SelectTrigger className="pick" aria-label={label||placeholder}><SelectValue placeholder={placeholder}/></SelectTrigger><SelectContent><SelectItem value="__none">{placeholder}</SelectItem>{options.map(o=>{const v=typeof o==='string'?o:o.value;return <SelectItem key={v} value={v}>{typeof o==='string'?o:o.label}</SelectItem>})}</SelectContent></Select>}
function Field({label,children,wide=false}:{label:string,children:React.ReactNode,wide?:boolean}){return <label className={'field '+(wide?'wide':'')}><span>{label}</span>{children}</label>}
function Empty({icon:Icon=Store,title,description,action}:{icon?:any,title:string,description:string,action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3><p>{description}</p>{action}</div>}
function NavButton({n,active,onSelect}:{n:any,active:boolean,onSelect:()=>void}){const {setOpenMobile,isMobile}=useSidebar();const Icon=n[2];return <SidebarMenuItem><SidebarMenuButton isActive={active} onClick={()=>{onSelect();if(isMobile)setOpenMobile(false)}} className="nav-button"><Icon/><span>{n[1]}</span></SidebarMenuButton></SidebarMenuItem>}
export default function Dashboard({onSignOut}:{onSignOut:()=>void}){
const [data,setData]=useState<Row|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[authError,setAuthError]=useState(false),[demo,setDemo]=useState(false),[section,setSection]=useState('overview'),[query,setQuery]=useState(''),[filter,setFilter]=useState(''),[sellerFilter,setSellerFilter]=useState(''),[modal,setModal]=useState(''),[form,setForm]=useState<Row>({}),[items,setItems]=useState<Row[]>([]),[saving,setSaving]=useState(false),[detail,setDetail]=useState<Row|null>(null),[detailType,setDetailType]=useState('shop'),[formError,setFormError]=useState('');
const load=useCallback(async()=>{setLoading(true);setError('');try{const r=await workspaceRequest({cache:'no-store'});const j:any=await r.json();if(!r.ok){setAuthError(r.status===401);throw new Error(j.error)}setData(j);setAuthError(false)}catch(e:any){setError(e.message||'No pudimos cargar el panel.')}finally{setLoading(false)}},[]);
useEffect(()=>{if(new URLSearchParams(location.search).get('demo')==='1'){setDemo(true);setData(demoData());setLoading(false)}else void load()},[load]);
const go=(s:string)=>{setSection(s);setQuery('');setFilter('');setDetail(null)};
const admin=data?.viewer?.admin??true;
const shops:Row[]=data?.shops||[],sellers:Row[]=data?.sellers||[],orders:Row[]=data?.orders||[],visits:Row[]=data?.visits||[],payments:Row[]=data?.payments||[],commissions:Row[]=data?.commissions||[],kits:Row[]=data?.kits||[];
const shop=(s:string)=>shops.find(x=>x.id===s),seller=(s:string)=>sellers.find(x=>x.id===s);
const paid=(o:Row)=>payments.filter(p=>p.order_id===o.id).reduce((a,p)=>a+p.amount,0);
const payState=(o:Row)=>paid(o)>=o.total?'Cobrado':paid(o)>0?'Parcial':'Pendiente';
const due=(o:Row)=>o.status==='Cancelado'?0:Math.max(0,o.total-paid(o));
const stats:Row[]=sellers.map(s=>({...s,...commissionSummary(orders,payments,commissions,s.id)}));
const nextShops=shops.filter(s=>s.next_visit&&s.next_visit<=today()&&!['No interesado','Cerrado'].includes(s.status)).sort((a,b)=>a.next_visit.localeCompare(b.next_visit));
const activeOrders=orders.filter(o=>!['Entregado','Cancelado'].includes(o.status));
const filteredShops=shops.filter(s=>(!sellerFilter||s.seller_id===sellerFilter)&&(!filter||s.status===filter)&&(s.name+' '+s.address+' '+s.zone+' '+s.contact).toLowerCase().includes(query.toLowerCase()));
const filteredOrders=orders.filter(o=>(!sellerFilter||o.seller_id===sellerFilter)&&(!filter||o.status===filter)&&(o.id+' '+(shop(o.shop_id)?.name||'')+' '+(seller(o.seller_id)?.name||'')).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.created.localeCompare(a.created));
function open(kind:string,initial:Row={}){setFormError('');setModal(kind);const settings=data?.settings||defaults;
if(kind==='shop')setForm({name:'',address:'',zone:'',contact:'',phone:'',seller_id:'',status:'Pendiente',next_visit:'',map_url:'',notes:'',...initial});
if(kind==='seller')setForm({name:'',email:'',phone:'',zone:'',map_url:'',active:1,...initial});
if(kind==='visit')setForm({id:id('VIS-'),shop_id:'',result:'Interesado',notes:'',next_visit:'',...initial});
if(kind==='order'){setForm({id:id('PED-'),shop_id:'',delivery:'',notes:'',...initial});setItems([{model:models[0],color:'Naranja',quantity:1,price:settings.price}])}
if(kind==='payment')setForm({id:id('COB-'),order_id:'',amount:'',method:'Transferencia',reference:'',...initial});
if(kind==='commission')setForm({id:id('COM-'),seller_id:'',amount:'',reference:'',...initial});
if(kind==='kit')setForm({id:id('KIT-'),seller_id:'',description:'',quantity:1,...initial});
if(kind==='cancel')setForm(initial);
}
const update=(k:string,v:any)=>setForm(f=>({...f,[k]:v}));
async function mutate(action:string,payload:Row){if(demo)throw new Error('Estás en el ejemplo. Salí del ejemplo para guardar datos reales.');const r=await workspaceRequest({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data:payload})});const j:any=await r.json();if(!r.ok)throw new Error(j.error);await load();return j}
async function submit(e:React.FormEvent){e.preventDefault();setSaving(true);setFormError('');try{const payload={...form};if(modal==='order')payload.items=items;if(['payment','commission'].includes(modal))payload.amount=Number(form.amount);if(modal==='kit')payload.quantity=Number(form.quantity);await mutate(modal,payload);setModal('');toast.success('Guardado correctamente');}catch(e:any){setFormError(e.message)}finally{setSaving(false)}}
async function action(name:string,payload:Row){setSaving(true);try{await mutate(name,payload);toast.success('Actualizado');if(name==='orderStatus')setDetail(d=>d?{...d,status:payload.status}:d)}catch(e:any){toast.error(e.message)}finally{setSaving(false)}}
function viewShop(s:Row){setDetail(s);setDetailType('shop')}
function viewOrder(o:Row){setDetail(o);setDetailType('order')}
const realDetail=detail?(detailType==='shop'?shop(detail.id):orders.find(o=>o.id===detail.id))||detail:null;
function download(){const rows:Row[]=section==='shops'||section==='routes'?shops:section==='visits'?visits:section==='sellers'?sellers:section==='kits'?kits:section==='payments'?[...payments.map(p=>({...p,tipo:'Cobro'})),...commissions.map(c=>({...c,tipo:'Comisión'}))]:orders;const columns=Object.keys(rows[0]||{});const cell=(v:any)=>{let t=typeof v==='object'?JSON.stringify(v):String(v??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'};const txt='\uFEFF'+[columns.map(cell).join(';'),...rows.map(r=>columns.map(k=>cell(r[k])).join(';'))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));a.download='Patas_a_Casa_'+section+'_'+today()+'.csv';a.click();URL.revokeObjectURL(a.href)}
function backup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='Patas_a_Casa_respaldo_'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}
useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const life=new AbortController();const reg=(x:any)=>Promise.resolve(context.registerTool(x,{signal:life.signal})).catch(()=>{});reg({name:'consultar_gestion_comercial',title:'Consultar gestión comercial',description:'Devuelve comercios, pedidos y visitas visibles para la cuenta actual. No modifica datos.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input:any)=>{if(!input||Object.keys(input).length)throw new Error('No se aceptan parámetros');if(!data)throw new Error('Panel no disponible');return{ejemplo:demo,comercios:data.shops,pedidos:data.orders,visitas:data.visits}}});reg({name:'abrir_seccion_comercial',title:'Abrir sección',description:'Navega a una sección del panel sin guardar ni modificar registros.',inputSchema:{type:'object',properties:{seccion:{type:'string',enum:nav.map(n=>n[0])}},required:['seccion'],additionalProperties:false},annotations:{readOnlyHint:false},execute:(input:any)=>{if(!input||Object.keys(input).length!==1||!nav.some(n=>n[0]===input.seccion))throw new Error('Sección inválida');if(!data)throw new Error('Panel no disponible');if(!data.viewer.admin&&['sellers','settings'].includes(input.seccion))throw new Error('Acceso restringido');go(input.seccion);return{seccion:input.seccion}}});return()=>life.abort()},[data,demo]);
const primary=section==='sellers'?['seller','Nuevo vendedor']:section==='visits'?['visit','Registrar visita']:section==='kits'?['kit','Entregar material']:section==='payments'?['payment','Registrar cobro']:section==='shops'||section==='routes'?['shop','Nuevo comercio']:['order','Nuevo pedido'];
const titles:Row={overview:['Inicio de ventas','Lo importante de hoy: visitas, pedidos, cobros y comisiones.'],shops:['Comercios','Tu red de petshops y próximos puntos de venta.'],routes:['Recorridos','Elegí un comercio y abrí las indicaciones para llegar.'],visits:['Visitas','El historial de conversaciones y próximos pasos.'],orders:['Pedidos','Del primer pedido a la entrega, sin perder el detalle.'],payments:['Cobros y comisiones','Lo que falta cobrar y lo que corresponde abonar.'],sellers:['Tu equipo de ventas','Zonas, contactos y resultados de cada vendedor.'],kits:['Muestras y material','Controlá qué tiene cada vendedor.'],settings:['Condiciones comerciales','Una misma propuesta para todo el equipo.']};
return <SidebarProvider><Toaster position="top-center" richColors/><Sidebar className="app-sidebar"><SidebarHeader><div className="brand"><img src="/ventas/logo.svg" alt="Patas a Casa"/><span>GESTIÓN COMERCIAL</span></div></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>VENTAS</SidebarGroupLabel><SidebarMenu>{nav.filter(n=>admin||!['sellers','settings'].includes(n[0])).map(n=><NavButton key={n[0]} n={n} active={section===n[0]} onSelect={()=>go(n[0])}/>)}</SidebarMenu></SidebarGroup><div className="sidebar-note"><PawPrint size={22}/><p>Más comercios.<br/><strong>Más reencuentros.</strong></p></div></SidebarContent><SidebarFooter><div className="profile"><span className="avatar">{admin?'PA':data?.viewer?.name?.slice(0,2).toUpperCase()||'PA'}</span><div><strong>{admin?'Administración':data?.viewer?.name}</strong><small>{demo?'Vista de ejemplo':'Patas a Casa'}</small></div><button className="icon-button" title="Cerrar sesión" aria-label="Cerrar sesión" onClick={onSignOut}><LogOut size={17}/></button></div></SidebarFooter></Sidebar>
<SidebarInset className="workspace"><header className="topbar"><div className="crumb"><SidebarTrigger/><span>Patas a Casa</span><ChevronRight size={14}/><strong>{nav.find(n=>n[0]===section)?.[1]}</strong></div><div className="top-right"><span className="private-label"><ShieldCheck size={14}/> Espacio privado</span><button className="icon-button" title="Actualizar datos" aria-label="Actualizar datos" onClick={()=>demo?toast.info('Estás viendo datos de ejemplo.'):load()}><RefreshCw size={17}/></button></div></header>
{demo&&<div className="demo-banner"><Info size={17}/><span>Estás viendo un ejemplo. Estos comercios y ventas son ficticios.</span><button onClick={()=>{setDemo(false);setData(null);history.replaceState({},'',location.pathname);void load()}}>Salir del ejemplo</button></div>}
<main className="main-content"><div className="page-heading"><div><div className="eyebrow">{section==='overview'?'PATAS A CASA · MENDOZA':'GESTIÓN COMERCIAL'}</div><h1>{titles[section][0]}</h1><p>{titles[section][1]}</p></div>{data&&section!=='settings'&&<div className="heading-actions"><button className="button secondary export-button" onClick={download}><Download size={16}/> Exportar</button>{(admin||['order','visit'].includes(primary[0]))&&<button className="button primary" onClick={()=>open(primary[0])}><Plus size={18}/>{primary[1]}</button>}</div>}</div>
{error&&!demo&&<div className="error-panel"><AlertCircle/><h3>{authError?'Ingresá a tu gestión comercial':'No pudimos abrir el panel'}</h3><p>{error}</p><div className="actions">{authError?<button className="button primary" onClick={onSignOut}>Volver a ingresar <ArrowRight size={16}/></button>:<button className="button primary" onClick={load}>Reintentar</button>}<button className="button secondary" onClick={()=>{setDemo(true);setData(demoData());setError('')}}>Ver un ejemplo</button></div></div>}
{loading&&!data&&!error&&<div className="stats-grid">{[1,2,3,4].map(n=><Skeleton key={n} className="h-36 rounded-xl"/>)}</div>}
{data&&<>
{section==='overview'&&<><div className="stats-grid"><Stat title="Comercios registrados" value={shops.length} icon={Store} detail={`${shops.filter(s=>s.status==='Cliente').length} clientes activos`} color="blue"/><Stat title="Pedidos en marcha" value={activeOrders.length} icon={ShoppingBag} detail={`${activeOrders.reduce((a,o)=>a+o.units,0)} chapitas por entregar`} color="orange"/><Stat title="Por cobrar" value={money(orders.reduce((a,o)=>a+due(o),0))} icon={Wallet} detail={`${orders.filter(o=>due(o)>0).length} pedidos con saldo pendiente`} color="purple"/><Stat title="Comisiones por abonar" value={money(stats.reduce((a,s)=>a+s.due,0))} icon={Users} detail="De pedidos cobrados por completo" color="teal"/></div>
<section className="quick-actions-panel"><div className="quick-actions-heading"><div><span className="mini-tag">ACCESOS RÁPIDOS</span><h2>¿Qué querés hacer?</h2></div><small>Las tareas más usadas, a un toque.</small></div><div className="quick-actions">{admin&&<button className="quick-action" onClick={()=>open('shop')}><span className="quick-action-icon"><Store size={20}/></span><span className="quick-action-copy"><strong>Nuevo comercio</strong><small>Cargá un petshop y asignalo.</small></span><ChevronRight size={18}/></button>}<button className="quick-action" disabled={!shops.length} onClick={()=>open('visit')}><span className="quick-action-icon"><ClipboardList size={20}/></span><span className="quick-action-copy"><strong>Registrar visita</strong><small>Anotá qué pasó y cuándo volver.</small></span><ChevronRight size={18}/></button><button className="quick-action emphasized" disabled={!shops.length} onClick={()=>open('order')}><span className="quick-action-icon"><ShoppingBag size={20}/></span><span className="quick-action-copy"><strong>Nuevo pedido</strong><small>Modelos, colores y cantidades.</small></span><ChevronRight size={18}/></button>{admin&&<button className="quick-action" onClick={()=>open('seller')}><span className="quick-action-icon"><Users size={20}/></span><span className="quick-action-copy"><strong>Nuevo vendedor</strong><small>Creá su acceso y asigná su zona.</small></span><ChevronRight size={18}/></button>}</div></section>
{!shops.length&&<section className="getting-started"><div className="start-copy"><span className="mini-tag">TU PRIMER PASO</span><h2>Armemos tu red de comercios.</h2><p>Cargá tu equipo y sus petshops. Después, cada visita y pedido quedará en un solo lugar.</p><button className="text-button" onClick={()=>{setDemo(true);setData(demoData())}}>Ver cómo se ve con datos de ejemplo <ArrowUpRight size={16}/></button></div><div className="start-steps">{[{n:'01',t:'Sumá a tu equipo',d:'Nombre, correo y zona de cada vendedor.',kind:'seller',done:sellers.length>0},{n:'02',t:'Cargá un comercio',d:'Su dirección, contacto y vendedor asignado.',kind:'shop',done:false},{n:'03',t:'Registrá tu primer pedido',d:'Elegí modelos, colores y cantidades.',kind:'order',done:orders.length>0}].map(s=><button key={s.n} className="start-step" onClick={()=>open(s.kind)} disabled={!admin&&s.kind!=='order'}><span className={s.done?'step done':'step'}>{s.done?<Check size={17}/>:s.n}</span><span><strong>{s.t}</strong><small>{s.d}</small></span><ChevronRight size={17}/></button>)}</div></section>}
<div className="overview-grid"><section className="panel"><div className="panel-heading"><h2><CalendarDays size={19}/> Próximas visitas</h2><button className="text-button" onClick={()=>go('routes')}>Ver recorridos <ArrowUpRight size={16}/></button></div>{nextShops.length?nextShops.slice(0,5).map(s=><div className="visit-row" key={s.id}><div className="date-chip"><CalendarDays size={19}/><span>{date(s.next_visit)}</span></div><div className="grow"><button className="name-button" onClick={()=>viewShop(s)}>{s.name}</button><p>{s.zone||s.address} · {seller(s.seller_id)?.name||'Sin asignar'}</p></div><a href={directions(s)} target="_blank" rel="noreferrer" className="icon-button" aria-label={'Cómo llegar a '+s.name}><Navigation size={18}/></a></div>):<Empty icon={CalendarDays} title="Sin visitas pendientes" description="Agendá el próximo contacto al cargar un comercio o registrar una visita." action={<button className="button secondary" onClick={()=>go('shops')}>Ver comercios</button>}/>}</section><section className="panel"><div className="panel-heading"><h2><ShoppingBag size={19}/> Últimos pedidos</h2><button className="text-button" onClick={()=>go('orders')}>Ver todos <ArrowUpRight size={16}/></button></div>{orders.length?orders.slice().sort((a,b)=>b.created.localeCompare(a.created)).slice(0,5).map(o=><button className="recent-order" key={o.id} onClick={()=>viewOrder(o)}><span className="order-icon"><ShoppingBag size={19}/></span><span className="grow"><strong>{shop(o.shop_id)?.name||o.shop_id}</strong><small>{o.units} chapitas · {date(o.created)}</small></span><span><strong>{money(o.total)}</strong><Badge value={o.status}/></span></button>):<Empty icon={ShoppingBag} title="Acá empieza tu próxima venta" description="Registrá el pedido y seguí su preparación, entrega y cobro." action={<button className="button primary" onClick={()=>open('order')}><Plus size={16}/> Nuevo pedido</button>}/>}</section></div><div className="commission-strip"><span className="strip-icon"><Receipt size={22}/></span><div><strong>Tu regla de comisión, siempre clara.</strong><p>$7.000 cada 4 chapitas de pedidos cobrados. Las unidades restantes se acumulan por vendedor.</p></div><button className="text-button" onClick={()=>go('payments')}>Ver comisiones <ArrowRight size={17}/></button></div></>}
{['shops','routes','orders','visits'].includes(section)&&<div className="filters"><div className="search"><Search size={18}/><input aria-label="Buscar" placeholder={section==='orders'?'Buscar pedido o comercio…':'Buscar comercio, zona o contacto…'} value={query} onChange={e=>setQuery(e.target.value)}/></div>{admin&&<Pick label="Filtrar por vendedor" value={sellerFilter} onChange={setSellerFilter} placeholder="Todos los vendedores" options={sellers.map(s=>({value:s.id,label:s.name}))}/>}{['shops','orders','routes'].includes(section)&&<Pick label="Filtrar por estado" value={filter} onChange={setFilter} placeholder="Todos los estados" options={section==='orders'?[...orderStates]:[...shopStates]}/>}</div>}
{section==='shops'&&<section className="panel">{filteredShops.length?<Table><TableHeader><TableRow><TableHead>COMERCIO</TableHead><TableHead>VENDEDOR</TableHead><TableHead>ESTADO</TableHead><TableHead>PRÓXIMA VISITA</TableHead><TableHead/></TableRow></TableHeader><TableBody>{filteredShops.map(s=><TableRow key={s.id}><TableCell><button className="name-button" onClick={()=>viewShop(s)}>{s.name}</button><small className="subtext"><MapPin size={12}/>{s.address}</small></TableCell><TableCell>{seller(s.seller_id)?.name||'Sin asignar'}</TableCell><TableCell><Badge value={s.status}/></TableCell><TableCell>{date(s.next_visit)}</TableCell><TableCell><button className="icon-button" aria-label={'Ver '+s.name} onClick={()=>viewShop(s)}><ChevronRight size={18}/></button></TableCell></TableRow>)}</TableBody></Table>:<Empty title={shops.length?'Sin coincidencias':'Tu red empieza con un comercio'} description={shops.length?'Probá con otro nombre o cambiá los filtros.':'Agregá un petshop con su dirección y asignalo a un vendedor.'} action={admin&&<button className="button primary" onClick={()=>open('shop')}><Plus size={16}/> Nuevo comercio</button>}/>}</section>}
{section==='routes'&&<><div className="map-links">{sellers.filter(s=>!sellerFilter||s.id===sellerFilter).map(s=><div className="map-link-card" key={s.id}><MapPinned size={23}/><div className="grow"><strong>{s.name}</strong><small>{s.zone||'Zona por definir'}</small></div>{s.map_url?<a href={s.map_url} target="_blank" rel="noreferrer" className="button secondary">Mapa compartido <ExternalLink size={15}/></a>:admin?<button className="text-button" onClick={()=>open('seller',s)}>Vincular My Maps <Plus size={15}/></button>:<small>Mapa sin vincular</small>}</div>)}</div><div className="route-grid">{filteredShops.map(s=><article className="route-card" key={s.id}><div className="route-top"><span className="round-icon"><Store size={21}/></span><Badge value={s.status}/></div><h3>{s.name}</h3><p><MapPin size={15}/>{s.address}</p><small>{seller(s.seller_id)?.name||'Sin vendedor asignado'}</small>{s.next_visit&&<div className="route-date"><CalendarDays size={15}/> Próxima visita: {date(s.next_visit)}</div>}{s.notes&&<p className="route-note">{s.notes}</p>}<div className="route-actions"><a className="button primary" href={directions(s)} target="_blank" rel="noreferrer"><Navigation size={16}/> Cómo llegar</a><button className="button secondary" onClick={()=>open('visit',{shop_id:s.id})}>Registrar visita</button></div><button className="text-button" onClick={()=>viewShop(s)}>Ver ficha del comercio <ArrowRight size={15}/></button></article>)}</div>{!filteredShops.length&&<section className="panel"><Empty icon={MapPinned} title="Tu próximo recorrido empieza acá" description="Cargá los comercios y sus direcciones. Podés vincular también el mapa de My Maps de cada vendedor." action={admin&&<button className="button primary" onClick={()=>open('shop')}>Cargar comercio</button>}/></section>}</>}
{section==='visits'&&<section className="panel"><div className="panel-heading"><h2>Historial de visitas</h2><span className="count">{visits.length} registros</span></div>{visits.filter(v=>(!sellerFilter||v.seller_id===sellerFilter)&&((shop(v.shop_id)?.name||'')+' '+v.notes).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.created.localeCompare(a.created)).map(v=><div className="history-row" key={v.id}><span className="timeline-icon"><ClipboardList size={18}/></span><div className="grow"><div className="between"><button className="name-button" onClick={()=>shop(v.shop_id)&&viewShop(shop(v.shop_id)!)}>{shop(v.shop_id)?.name||v.shop_id}</button><Badge value={v.result}/></div><p>{v.notes||'Sin observaciones.'}</p><small>{date(v.created)} · {seller(v.seller_id)?.name||'Administración'}{v.next_visit?' · Volver: '+date(v.next_visit):''}</small></div></div>)}{!visits.length&&<Empty icon={ClipboardList} title="Cada visita deja un próximo paso" description="Anotá qué pasó, con quién hablaste y cuándo volver." action={<button className="button primary" onClick={()=>open('visit')}>Registrar visita</button>}/>}</section>}
{section==='orders'&&<section className="panel">{filteredOrders.length?<Table><TableHeader><TableRow><TableHead>PEDIDO / COMERCIO</TableHead><TableHead>CHAPITAS</TableHead><TableHead>TOTAL</TableHead><TableHead>PREPARACIÓN</TableHead><TableHead>COBRO</TableHead><TableHead>ENTREGA</TableHead><TableHead/></TableRow></TableHeader><TableBody>{filteredOrders.map(o=><TableRow key={o.id}><TableCell><button className="name-button" onClick={()=>viewOrder(o)}>{shop(o.shop_id)?.name||o.shop_id}</button><small className="subtext">{o.id} · {seller(o.seller_id)?.name||'Administración'}</small></TableCell><TableCell>{o.units}</TableCell><TableCell className="money">{money(o.total)}</TableCell><TableCell><Badge value={o.status}/></TableCell><TableCell><Badge value={o.status==='Cancelado'?'Cancelado':payState(o)}/></TableCell><TableCell>{date(o.delivery)}</TableCell><TableCell><button className="icon-button" onClick={()=>viewOrder(o)} aria-label={'Ver pedido '+o.id}><ChevronRight size={18}/></button></TableCell></TableRow>)}</TableBody></Table>:<Empty icon={ShoppingBag} title={orders.length?'No hay pedidos con esos filtros':'Listo para tu primera venta'} description="Cargá modelos, colores y cantidades. El total se calcula automáticamente." action={<button className="button primary" onClick={()=>open('order')}><Plus size={16}/> Nuevo pedido</button>}/>}</section>}
{section==='payments'&&<><div className="stats-grid three"><Stat title="Cobros registrados" value={money(payments.reduce((a,p)=>a+p.amount,0))} icon={CheckCircle2} detail="Pagos confirmados por administración" color="teal"/><Stat title="Saldo por cobrar" value={money(orders.reduce((a,o)=>a+due(o),0))} icon={Wallet} detail="Incluye pedidos con pagos parciales" color="orange"/><Stat title="Comisiones abonadas" value={money(commissions.reduce((a,c)=>a+c.amount,0))} icon={Users} detail="Pagos registrados a vendedores" color="blue"/></div><section className="panel"><div className="panel-heading"><h2>Comisiones por vendedor</h2><span className="small-note">$7.000 cada 4 chapitas cobradas</span></div>{stats.length?<div className="commission-cards">{stats.map(s=><div className="commission-card" key={s.id}><div className="person-line"><span className="avatar">{s.name.slice(0,2).toUpperCase()}</span><div><h3>{s.name}</h3><small>{s.units} chapitas de pedidos cobrados</small></div></div><div className="commission-amount">{money(s.due)}<span>por abonar</span></div><div className="commission-details"><span>Generado<strong>{money(s.earned)}</strong></span><span>Abonado<strong>{money(s.paid)}</strong></span></div><p>{s.remainder} de 4 chapitas para el próximo grupo.</p>{admin&&<button className="button primary full" disabled={!s.due} onClick={()=>open('commission',{seller_id:s.id,amount:s.due})}>Registrar pago de comisión</button>}</div>)}</div>:<Empty icon={Users} title="Sin comisiones todavía" description="Agregá vendedores y asignales comercios. Las comisiones se calculan con los pedidos cobrados por completo."/>}</section><section className="panel spaced"><div className="panel-heading"><h2>Pedidos pendientes de cobro</h2><span className="count">{orders.filter(o=>due(o)>0).length}</span></div>{orders.filter(o=>due(o)>0).map(o=><div className="balance-row" key={o.id}><div className="grow"><button className="name-button" onClick={()=>viewOrder(o)}>{shop(o.shop_id)?.name||o.shop_id}</button><small className="subtext">{o.id} · Cobrado: {money(paid(o))} de {money(o.total)}</small></div><strong>{money(due(o))}</strong>{admin&&<button className="button secondary" onClick={()=>open('payment',{order_id:o.id,amount:due(o)})}>Registrar cobro</button>}</div>)}{!orders.some(o=>due(o)>0)&&<div className="inline-empty"><CheckCircle2 size={20}/> No hay saldos pendientes.</div>}</section><section className="panel spaced"><div className="panel-heading"><h2>Movimientos</h2></div>{[...payments.map((p):Row=>({...p,kind:'Cobro',name:shop(orders.find(o=>o.id===p.order_id)?.shop_id)?.name||p.order_id})),...commissions.map((c):Row=>({...c,kind:'Comisión',name:seller(c.seller_id)?.name}))].sort((a,b)=>b.created.localeCompare(a.created)).map(p=><div className="balance-row" key={p.id}><span className="order-icon"><Receipt size={19}/></span><div className="grow"><strong>{p.kind} · {p.name}</strong><small className="subtext">{date(p.created)} · {p.method||'Pago a vendedor'}{p.reference?' · '+p.reference:''}</small></div><strong>{money(p.amount)}</strong></div>)}{!payments.length&&!commissions.length&&<p className="inline-empty">Los cobros y pagos registrados aparecerán acá.</p>}</section></>}
{section==='sellers'&&admin&&<><div className="seller-grid">{sellers.map(s=><article className="seller-card" key={s.id}><div className="between"><span className="avatar large">{s.name.split(' ').map((n:string)=>n[0]).slice(0,2).join('')}</span><Badge value={s.active?'Activo':'Inactivo'}/></div><h3>{s.name}</h3><p><MapPin size={15}/>{s.zone||'Sin zona asignada'}</p><p><Mail size={15}/>{s.email}</p><div className="seller-numbers"><span><strong>{shops.filter(x=>x.seller_id===s.id).length}</strong> comercios</span><span><strong>{orders.filter(x=>x.seller_id===s.id&&x.status!=='Cancelado').length}</strong> pedidos</span></div><div className="actions"><button className="button secondary" onClick={()=>open('seller',s)}>Editar vendedor</button><button className="text-button" onClick={()=>{setSellerFilter(s.id);go('routes')}}>Recorrido <ArrowRight size={16}/></button></div><AccessLink seller={s} disabled={demo}/></article>)}</div>{!sellers.length&&<section className="panel"><Empty icon={Users} title="Tu equipo empieza acá" description="Cargá el nombre, el correo y la zona de cada vendedor." action={<button className="button primary" onClick={()=>open('seller')}><Plus size={16}/> Nuevo vendedor</button>}/></section>}<div className="help-note"><ShieldCheck size={20}/><p>El correo identifica al vendedor cuando inicia sesión. Generá su enlace de acceso y compartíselo para que cree su contraseña. Cada vendedor ve sus comercios y sus ventas; los cobros los confirma administración.</p></div></>}
{section==='kits'&&<section className="panel">{kits.length?<Table><TableHeader><TableRow><TableHead>MATERIAL</TableHead><TableHead>VENDEDOR</TableHead><TableHead>CANTIDAD</TableHead><TableHead>FECHA</TableHead><TableHead>ESTADO</TableHead><TableHead/></TableRow></TableHeader><TableBody>{kits.map(k=><TableRow key={k.id}><TableCell>{k.description}</TableCell><TableCell>{seller(k.seller_id)?.name}</TableCell><TableCell>{k.quantity}</TableCell><TableCell>{date(k.created)}</TableCell><TableCell><Badge value={k.returned>=k.quantity?'Devuelto':'En poder del vendedor'}/></TableCell><TableCell>{admin&&k.returned<k.quantity&&<button disabled={saving} className="text-button" onClick={()=>action('kitReturn',{id:k.id})}>Registrar devolución</button>}</TableCell></TableRow>)}</TableBody></Table>:<Empty icon={Package} title="El muestrario también queda registrado" description="Anotá chapitas de muestra, packaging, tarjetas y cualquier material que entregues." action={admin&&<button className="button primary" onClick={()=>open('kit')}>Entregar material</button>}/>}</section>}
{section==='settings'&&admin&&<SettingsForm settings={data.settings} saving={saving} onSave={async(v)=>{setSaving(true);try{await mutate('settings',v);toast.success('Condiciones guardadas')}catch(e:any){toast.error(e.message)}finally{setSaving(false)}}} backup={backup}/>}
</>}
<footer className="workspace-footer"><span>Patas a Casa · Gestión comercial</span><span>{demo?'Datos ficticios de demostración':'Los cambios se guardan al confirmar cada formulario.'}</span></footer>
</main></SidebarInset>
<Dialog open={!!modal} onOpenChange={v=>{if(!saving&&!v)setModal('')}}><DialogContent className={'form-dialog '+(modal==='order'?'order-dialog':'')}><DialogHeader><DialogTitle>{({shop:form.id?'Editar comercio':'Nuevo comercio',seller:form.id?'Editar vendedor':'Nuevo vendedor',visit:'Registrar visita',order:'Nuevo pedido',payment:'Registrar cobro',commission:'Abonar comisión',kit:'Entregar material'} as Row)[modal]||'Confirmar'}</DialogTitle><DialogDescription>{({shop:'Guardá el contacto y organizá la próxima visita.',seller:'Asigná una zona y registrá su correo de acceso.',visit:'Dejá registrado el resultado y el próximo paso.',order:'Cargá el pedido con el detalle de cada chapita.',payment:'Confirmá únicamente el dinero que ya recibiste.',commission:'Registrá el pago que ya realizaste al vendedor.',kit:'El material quedará asociado al vendedor.'} as Row)[modal]}</DialogDescription></DialogHeader>
<form onSubmit={submit} className="editor-form"><div className="form-grid">
{modal==='shop'&&<><Field label="Nombre del comercio *" wide><input required minLength={2} value={form.name||''} onChange={e=>update('name',e.target.value)} placeholder="Ej.: Huellitas Petshop"/></Field><Field label="Dirección completa *" wide><input required value={form.address||''} onChange={e=>update('address',e.target.value)} placeholder="Calle, número, localidad y Mendoza"/></Field><Field label="Zona"><input value={form.zone||''} onChange={e=>update('zone',e.target.value)} placeholder="Ej.: Guaymallén"/></Field><Field label="Vendedor asignado"><Pick value={form.seller_id||''} onChange={v=>update('seller_id',v)} placeholder="Sin asignar" options={sellers.filter(s=>s.active||s.id===form.seller_id).map(s=>({value:s.id,label:s.name}))}/></Field><Field label="Persona de contacto"><input value={form.contact||''} onChange={e=>update('contact',e.target.value)} placeholder="Nombre del encargado"/></Field><Field label="WhatsApp (con código de país)"><input type="tel" value={form.phone||''} onChange={e=>update('phone',e.target.value)} placeholder="Ej.: 549261…"/></Field><Field label="Estado"><Pick value={form.status||''} onChange={v=>update('status',v)} options={[...shopStates]}/></Field><Field label="Próxima visita"><input type="date" value={form.next_visit||''} onChange={e=>update('next_visit',e.target.value)}/></Field><Field label="Enlace del lugar en Google Maps" wide><input type="url" value={form.map_url||''} onChange={e=>update('map_url',e.target.value)} placeholder="https://maps.app.goo.gl/…"/></Field><Field label="Horario, indicaciones u observaciones" wide><textarea rows={3} value={form.notes||''} onChange={e=>update('notes',e.target.value)} placeholder="Ej.: preguntar por Laura de 9 a 12 h"/></Field></>}
{modal==='seller'&&<><Field label="Nombre completo *" wide><input required value={form.name||''} onChange={e=>update('name',e.target.value)}/></Field><Field label="Correo electrónico *" wide><input type="email" required value={form.email||''} onChange={e=>update('email',e.target.value)}/></Field><Field label="WhatsApp"><input type="tel" value={form.phone||''} onChange={e=>update('phone',e.target.value)}/></Field><Field label="Zona de trabajo"><input value={form.zone||''} onChange={e=>update('zone',e.target.value)} placeholder="Guaymallén"/></Field><Field label="Enlace a su mapa compartido de My Maps" wide><input type="url" value={form.map_url||''} onChange={e=>update('map_url',e.target.value)} placeholder="Pegá el enlace del mapa"/></Field><Field label="Estado"><Pick value={String(form.active??1)} onChange={v=>update('active',Number(v))} options={[{value:'1',label:'Activo'},{value:'0',label:'Inactivo'}]}/></Field><div className="form-hint wide">Después de guardar, usá «Crear enlace de acceso» en su ficha y compartíselo al vendedor.</div></>}
{['visit','order'].includes(modal)&&<Field label="Comercio *" wide><Pick label="Comercio" value={form.shop_id||''} onChange={v=>update('shop_id',v)} placeholder="Seleccioná un comercio" options={shops.map(s=>({value:s.id,label:s.name}))}/>{!shops.length&&<small>Primero cargá un comercio desde la sección Comercios.</small>}</Field>}
{modal==='visit'&&<><Field label="Resultado *"><Pick value={form.result||''} onChange={v=>update('result',v)} options={[...visitResults]}/></Field><Field label="Volver a visitar el"><input type="date" value={form.next_visit||''} onChange={e=>update('next_visit',e.target.value)}/></Field><Field label="¿Qué conversaron?" wide><textarea rows={4} value={form.notes||''} onChange={e=>update('notes',e.target.value)} placeholder="Con quién hablaste, qué pidió y el próximo paso…"/></Field>{form.result==='Hizo pedido'&&<div className="form-hint wide">Esta visita no crea un pedido. Cargá también los modelos y cantidades en Nuevo pedido.</div>}</>}
{modal==='order'&&<><div className="wide order-items"><div className="between"><strong>Detalle de chapitas</strong><button type="button" className="text-button" onClick={()=>setItems(x=>[...x,{model:models[0],color:'Naranja',quantity:1,price:data?.settings.price||7000}])}><Plus size={15}/> Agregar modelo</button></div>{items.map((i,n)=><div className="order-item" key={n}><Field label="Modelo"><Pick value={i.model} onChange={v=>setItems(a=>a.map((x,j)=>j===n?{...x,model:v}:x))} options={models}/></Field><Field label="Color"><Pick value={i.color} onChange={v=>setItems(a=>a.map((x,j)=>j===n?{...x,color:v}:x))} options={colors}/></Field><Field label="Cantidad"><input required type="number" min="1" max="10000" value={i.quantity} onChange={e=>setItems(a=>a.map((x,j)=>j===n?{...x,quantity:Number(e.target.value)}:x))}/></Field><Field label="Precio unitario"><input required type="number" min="1" disabled={!admin} value={i.price} onChange={e=>setItems(a=>a.map((x,j)=>j===n?{...x,price:Number(e.target.value)}:x))}/></Field><button type="button" className="icon-button" aria-label={'Quitar modelo '+(n+1)} disabled={items.length===1} onClick={()=>setItems(a=>a.filter((_,j)=>j!==n))}><Trash2 size={16}/></button></div>)}</div><Field label="Entrega solicitada"><input type="date" value={form.delivery||''} onChange={e=>update('delivery',e.target.value)}/></Field><Field label="Observaciones" wide><textarea rows={2} value={form.notes||''} onChange={e=>update('notes',e.target.value)} placeholder="Horario de entrega o pedido especial"/></Field><div className="order-total wide"><span>{items.reduce((a,i)=>a+i.quantity,0)} chapitas</span><strong>Total: {money(items.reduce((a,i)=>a+i.quantity*i.price,0))}</strong></div><div className="form-hint wide">El pedido queda recibido. Administración confirma disponibilidad y entrega.</div></>}
{modal==='payment'&&<><Field label="Pedido *" wide><Pick value={form.order_id||''} onChange={v=>{update('order_id',v);const o=orders.find(x=>x.id===v);update('amount',o?due(o):'')}} options={orders.filter(o=>due(o)>0).map(o=>({value:o.id,label:`${shop(o.shop_id)?.name||o.shop_id} · ${o.id} · ${money(due(o))}`}))}/></Field><Field label="Importe recibido *"><input required type="number" min="1" step="1" value={form.amount??''} onChange={e=>update('amount',e.target.value)}/></Field><Field label="Medio de pago"><Pick value={form.method||''} onChange={v=>update('method',v)} options={['Transferencia','Efectivo','Otro']}/></Field><Field label="Referencia o comprobante" wide><input value={form.reference||''} onChange={e=>update('reference',e.target.value)} placeholder="Ej.: número de transferencia"/></Field><div className="form-hint wide">Podés registrar pagos parciales. La comisión se habilita cuando el pedido está cobrado por completo.</div></>}
{modal==='commission'&&<><Field label="Vendedor *" wide><Pick value={form.seller_id||''} onChange={v=>{update('seller_id',v);update('amount',stats.find(s=>s.id===v)?.due||0)}} options={stats.filter(s=>s.due>0).map(s=>({value:s.id,label:s.name+' · disponible '+money(s.due)}))}/></Field><Field label="Importe abonado *"><input required type="number" min="1" value={form.amount??''} onChange={e=>update('amount',e.target.value)}/></Field><Field label="Referencia del pago" wide><input value={form.reference||''} onChange={e=>update('reference',e.target.value)} placeholder="Transferencia, efectivo o número de comprobante"/></Field></>}
{modal==='kit'&&<><Field label="Vendedor *" wide><Pick value={form.seller_id||''} onChange={v=>update('seller_id',v)} options={sellers.filter(s=>s.active).map(s=>({value:s.id,label:s.name}))}/></Field><Field label="Material entregado *" wide><textarea required rows={3} value={form.description||''} onChange={e=>update('description',e.target.value)} placeholder="Ej.: chapita circular grande naranja con argolla"/></Field><Field label="Cantidad *"><input required type="number" min="1" value={form.quantity||1} onChange={e=>update('quantity',e.target.value)}/></Field></>}
</div>{formError&&<p role="alert" className="form-error"><AlertCircle size={17}/>{formError}</p>}<div className="form-actions"><button className="button secondary" type="button" disabled={saving} onClick={()=>setModal('')}>Cancelar</button><button className="button primary" type="submit" disabled={saving||(['order','visit'].includes(modal)&&!form.shop_id)}>{saving?<LoaderCircle className="spin" size={17}/>:<Check size={17}/>} {saving?'Guardando…':modal==='payment'?'Confirmar cobro':modal==='commission'?'Confirmar pago':'Guardar'}</button></div></form>
</DialogContent></Dialog>
<Sheet open={!!detail} onOpenChange={v=>!v&&setDetail(null)}><SheetContent className="detail-sheet"><SheetHeader><SheetTitle>{detailType==='shop'?realDetail?.name:realDetail?.id}</SheetTitle><SheetDescription>{detailType==='shop'?'Ficha del comercio':shop(realDetail?.shop_id)?.name||'Detalle del pedido'}</SheetDescription></SheetHeader>{realDetail&&<div className="detail-body">{detailType==='shop'?<><Badge value={realDetail.status}/><p className="detail-address"><MapPin size={18}/>{realDetail.address}</p><div className="actions"><a href={directions(realDetail)} target="_blank" rel="noreferrer" className="button primary"><Navigation size={17}/> Cómo llegar</a>{realDetail.phone&&<a href={phone(realDetail.phone)} target="_blank" rel="noreferrer" className="button secondary"><Phone size={16}/> WhatsApp</a>}</div>{realDetail.map_url&&<a className="text-button" target="_blank" rel="noreferrer" href={realDetail.map_url}>Abrir ubicación guardada <ExternalLink size={15}/></a>}<dl className="detail-grid"><dt>Contacto</dt><dd>{realDetail.contact||'Sin registrar'}</dd><dt>Vendedor</dt><dd>{seller(realDetail.seller_id)?.name||'Sin asignar'}</dd><dt>Próxima visita</dt><dd>{date(realDetail.next_visit)}</dd><dt>Código</dt><dd>{realDetail.id}</dd></dl>{realDetail.notes&&<div className="note-box">{realDetail.notes}</div>}<div className="actions"><button className="button secondary" onClick={()=>open('visit',{shop_id:realDetail.id})}>Registrar visita</button><button className="button primary" onClick={()=>open('order',{shop_id:realDetail.id})}><Plus size={16}/> Nuevo pedido</button></div>{admin&&<button className="text-button" onClick={()=>open('shop',realDetail)}>Editar comercio <ArrowRight size={15}/></button>}<h3>Últimas visitas</h3>{visits.filter(v=>v.shop_id===realDetail.id).sort((a,b)=>b.created.localeCompare(a.created)).map(v=><div className="detail-history" key={v.id}><div className="between"><Badge value={v.result}/><small>{date(v.created)}</small></div><p>{v.notes||'Sin notas'}</p></div>)}{!visits.some(v=>v.shop_id===realDetail.id)&&<p className="muted">Todavía no hay visitas registradas.</p>}<h3>Pedidos</h3>{orders.filter(o=>o.shop_id===realDetail.id).map(o=><button key={o.id} className="recent-order" onClick={()=>viewOrder(o)}><span className="grow"><strong>{o.id}</strong><small>{o.units} chapitas</small></span><strong>{money(o.total)}</strong><ChevronRight size={16}/></button>)}</>:<><div className="between"><Badge value={realDetail.status}/><Badge value={payState(realDetail)}/></div><dl className="detail-grid"><dt>Vendedor</dt><dd>{seller(realDetail.seller_id)?.name||'Administración'}</dd><dt>Creado</dt><dd>{date(realDetail.created)}</dd><dt>Entrega solicitada</dt><dd>{date(realDetail.delivery)}</dd></dl>{realDetail.items.map((i:Row,n:number)=><div className="detail-line" key={n}><span><strong>{i.model}</strong><small>{i.color} · {i.quantity} × {money(i.price)}</small></span><strong>{money(i.quantity*i.price)}</strong></div>)}<div className="order-total"><span>Total</span><strong>{money(realDetail.total)}</strong></div><div className="between"><span>Cobrado</span><strong>{money(paid(realDetail))}</strong></div><div className="between"><span>Pendiente</span><strong>{money(due(realDetail))}</strong></div>{realDetail.notes&&<div className="note-box">{realDetail.notes}</div>}{admin&&realDetail.status!=='Cancelado'&&<><Field label="Estado del pedido"><Pick value={realDetail.status} onChange={v=>v&&action('orderStatus',{id:realDetail.id,status:v})} options={orderStates.filter(s=>s!=='Cancelado') as unknown as string[]}/></Field>{due(realDetail)>0&&<button className="button primary full" onClick={()=>open('payment',{order_id:realDetail.id,amount:due(realDetail)})}><Wallet size={17}/> Registrar cobro</button>}{paid(realDetail)===0&&<CancelOrder disabled={saving} onConfirm={()=>action('orderStatus',{id:realDetail.id,status:'Cancelado'})}/>}</>}</>} </div>}</SheetContent></Sheet>
</SidebarProvider>}
function Stat({title,value,icon:Icon,detail,color}:any){return <div className={'stat-card '+color}><div className="between"><span>{title}</span><div className="stat-icon"><Icon size={19}/></div></div><strong className="stat-value">{value}</strong><small>{detail}</small></div>}
function SettingsForm({settings,saving,onSave,backup}:{settings:Row,saving:boolean,onSave:(s:Row)=>void,backup:()=>void}){const [s,setS]=useState(settings);return <div className="settings-grid"><section className="panel settings-panel"><h2>Propuesta para petshops</h2><p className="muted">Los cambios de precio se aplican a pedidos nuevos.</p><form onSubmit={e=>{e.preventDefault();onSave(s)}}><div className="form-grid"><Field label="Precio por chapita al comercio ($) *"><input required type="number" min="1" value={s.price} onChange={e=>setS({...s,price:Number(e.target.value)})}/></Field><Field label="Precio sugerido al público"><input value={s.retail} onChange={e=>setS({...s,retail:e.target.value})} placeholder="A definir"/></Field><Field label="Pedido mínimo"><input value={s.minimum} onChange={e=>setS({...s,minimum:e.target.value})} placeholder="A definir"/></Field><Field label="WhatsApp de Patas a Casa"><input value={s.phone} onChange={e=>setS({...s,phone:e.target.value})} placeholder="549261…"/></Field><Field label="Condiciones de entrega" wide><textarea value={s.delivery} onChange={e=>setS({...s,delivery:e.target.value})} placeholder="Quién entrega, plazos y zonas"/></Field><Field label="Otros administradores (correos separados por coma)" wide><textarea value={s.adminEmails||''} onChange={e=>setS({...s,adminEmails:e.target.value})} placeholder="Correo de tu socio o de quien administre con vos"/><small>Podrán ver y gestionar todo. Deben tener una cuenta de Patas a Casa con ese correo.</small></Field><Field label="Condiciones de pago" wide><textarea value={s.payment} onChange={e=>setS({...s,payment:e.target.value})} placeholder="Medios de pago y momento de cobro"/></Field></div><button className="button primary" disabled={saving} type="submit"><Check size={16}/> Guardar condiciones</button></form></section><div><section className="panel settings-panel commission-policy"><Receipt size={27}/><h2>Comisiones</h2><div className="policy-number">$7.000 <span>/ cada 4 chapitas</span></div><p>Se suman las unidades de pedidos cobrados por completo de cada vendedor. Las restantes quedan acumuladas.</p><p>Los pedidos con pagos parciales habilitan la comisión cuando se completa el cobro.</p><p>El sistema calcula el saldo. Administración registra el pago al vendedor cuando lo realiza.</p></section><section className="panel settings-panel spaced"><h2>Respaldo de tus datos</h2><p className="muted">Descargá una copia completa de los registros en formato JSON. Cada sección también se puede exportar para Excel.</p><button className="button secondary" onClick={backup}><Download size={16}/> Descargar respaldo</button></section></div></div>}
import {AlertDialog,AlertDialogTrigger,AlertDialogContent,AlertDialogHeader,AlertDialogTitle,AlertDialogDescription,AlertDialogFooter,AlertDialogCancel,AlertDialogAction} from '@/components/ui/alert-dialog';
function CancelOrder({disabled,onConfirm}:{disabled:boolean,onConfirm:()=>void}){return <AlertDialog><AlertDialogTrigger asChild><button className="text-button danger" disabled={disabled}>Cancelar este pedido</button></AlertDialogTrigger><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>¿Cancelar el pedido?</AlertDialogTitle><AlertDialogDescription>Se conservará el historial, pero el pedido dejará de contar como venta pendiente. Esta acción no se puede revertir.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Volver</AlertDialogCancel><AlertDialogAction onClick={onConfirm}>Confirmar cancelación</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
